// ═══════ PROMPT ═══════
var promptType='cover';
function setPromptType(t){
  promptType=t;
  document.getElementById('ptCover').className='btn '+(t==='cover'?'btn-primary':'btn-ghost');
  document.getElementById('ptCommunity').className='btn '+(t==='community'?'btn-primary':'btn-ghost');
}

function genPrompt(){
  var product=document.getElementById("promptProduct").value.trim()||"招牌鲜果切";
  var scene=document.getElementById("promptScene").value;
  var btn=document.getElementById("btnGenPrompt");
  var el=document.getElementById("promptOutput");
  var typeName=promptType==='cover'?'小程序封面':'社群群发';
  var ratio=promptType==='cover'?'1:1正方形':'3:4竖版';
  
  if(scene==="brand"||scene==="social"){
    var logoRule=scene==="brand"
      ? "图1（产品白底图）强制规则：果盒、容器、果肉种类与摆放完整原样复刻，不得修改、增减水果；完整保留原图LOGO图案，LOGO统一放置画面左上角，随"+ratio+"画幅等比例适配缩放，禁止消除、扭曲、移位至其他区域。"
      : "图1（产品白底图）强制规则：果盒、容器、果肉种类与摆放完整原样复刻，不得修改、增减水果；LOGO可直接去除弱化。";
    var txt="根据上传两张图片生成果切实拍图。\n\n"+logoRule+"\n\n"+
      "2.图2（博主氛围参考图）通用参考范围：保留画面整体光影色调、构图留白、桌面布景、餐具搭配、人物手持/摆放姿势、生活化氛围感、背景虚化层次；仅忽略图内博主手中盛放的水果、餐食、原装容器，禁止照搬这份食物形态。\n\n"+
      "3.版权约束：仅借鉴拍摄风格与布局逻辑，生成全新原创场景，不完整复刻博主原图道具、背景细节。\n\n"+
      "4.画质底线：原生实拍质感，禁用3D塑料建模感、高饱和刺眼色彩、厚重黑影、廉价塑料装饰；画面留白充足，产品始终清晰突出。\n\n"+
      "5.规格："+ratio+"4K高清，无多余文字、无水印。";
    el.innerHTML=renderPromptCard(txt,typeName+'·博主参考',"📸");
    return;
  }
  
  btn.disabled=true;btn.textContent="⏳ 生成中...";
  el.innerHTML="<div style=\"text-align:center;padding:40px;color:var(--text-dim)\">⏳ AI 正在为你创作配图 Prompt...</div>";
  
  var sceneNames={hot:"热销爆品·精致质感",member:"会员日·清新仪式感",weekend:"周末·窗边松弛感",grass:"种草·高级食欲感",ice:"特价·极简冰镇感"};
  var sceneName=sceneNames[scene]||"精致质感";
  
  var apiKey=getApiKey();
  if(!apiKey){el.innerHTML="<div style=\"text-align:center;padding:40px;color:var(--red)\">⚠️ 请先设置 API Key</div>";btn.disabled=false;btn.textContent="🧠 生成 Prompt";return;}
  
  var promptText="你是食物摄影布景专家。用户将上传一张产品白底图+一张博主参考图到AI生图工具。\\n"+
    "产品名称「"+product+"」仅作场景搭配参考——产品外观以白底图为准，你不需描述产品形态。\\n\\n"+
    "请根据场景「"+sceneName+"」写一段生图Prompt，用以下格式严格分段输出：\\\\n\\\\n"+
    "【画幅】"+ratio+"\\\\n"+
    "【产品】使用上传白底图中的产品，保持原样\\\\n"+
    "【构图】XXX（居中对称/三角构图/窗边纵深/极简留白选一种）\\\\n"+
    "【桌面光影】XXX（橡木/微水泥/大理石，柔光/侧光）\\\\n"+
    "【色调】XXX（清新明亮/暖调柔光/冷白冰镇感）\\\\n"+
    "【氛围】XXX（精致/松弛/高级/食欲感）\\\\n"+
    "【景深层次】前景→中景产品→后景虚化，4-6件道具\\\\n"+
    "【前景道具】XXX\\\\n"+
    "【背景】XXX\\\\n"+
    "【参考】博主参考图仅借鉴风格与布景逻辑\\\\n\\\\n"+
    "禁止：文字/LOGO/水印，3D建模感，高饱和，复刻博主原图道具。\\\\n"+
    "所有输出必须使用中文，不要任何英文。\\\\n"+
    "直接输出Prompt，不解释。";
  
  fetch("https://api.deepseek.com/chat/completions",{
    method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+apiKey},
    body:JSON.stringify({model:"deepseek-chat",messages:[{role:"user",content:promptText}],max_tokens:800})
  }).then(function(r){return r.json()}).then(function(d){
    var txt=d.choices?d.choices[0].message.content:"生成失败";
    el.innerHTML=renderPromptCard(txt,sceneName,"🧠");
    btn.disabled=false;btn.textContent="🧠 生成 Prompt";
  }).catch(function(e){
    el.innerHTML="<div style=\"text-align:center;padding:40px;color:var(--red)\">⚠️ "+e.message+"</div>";
    btn.disabled=false;btn.textContent="🧠 生成 Prompt";
  });
}

function renderPromptCard(text,label,badge){
  var id='pr_'+Date.now();
  // Store current prompt data for favoriting
  window._lastPrompt={text:text,label:label,id:id};
  return '<div style="background:#fff;border-radius:var(--radius-sm);padding:16px;border:1px solid var(--border)" id="'+id+'">'+
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">'+
    '<span style="font-size:12px;font-weight:600;color:var(--brand)">'+badge+' '+label+'</span>'+
    '<div style="display:flex;gap:6px">'+
    '<button class="btn btn-ghost" onclick="favPrompt(\''+id+'\')" style="font-size:11px;padding:4px 8px" title="收藏">⭐</button>'+
    '<button class="btn btn-ghost" onclick="navigator.clipboard.writeText(this.parentElement.parentElement.parentElement.querySelector(\'.prompt-body\').textContent);toast(\'📋 已复制\')" style="font-size:11px;padding:4px 8px">📋 复制</button>'+
    '<button class="btn btn-ghost" onclick="window.open(\'https://www.doubao.com/chat\',\'_blank\')" style="font-size:11px;padding:4px 8px">📱 豆包</button>'+
    '</div></div>'+
    '<div class="prompt-body" style="font-size:12px;line-height:1.8;color:var(--text);white-space:pre-wrap;background:var(--bg);padding:12px;border-radius:var(--radius-sm)">'+text+'</div>'+
    '</div>';
}

// ─── Prompt Favorites ───
var recipeType='cover';
var recipeCache={};

function setRecipeType(t){
  recipeType=t;
  document.getElementById('rtCover').className='btn '+(t==='cover'?'btn-primary':'btn-ghost');
  document.getElementById('rtCommunity').className='btn '+(t==='community'?'btn-primary':'btn-ghost');
  renderPromptLib();
  renderRecipeHistory();
}

function getRecipes(){try{return JSON.parse(localStorage.getItem('qg_prompt_recipes')||'{}');}catch(e){return{};}}
function saveRecipes(r){localStorage.setItem('qg_prompt_recipes',JSON.stringify(r));}
function favPrompt(cardId){
  var d=window._lastPrompt;
  if(!d||d.id!==cardId)return;
  var favs=getFavs();
  if(favs.some(function(f){return f.text===d.text;})){toast('⚠️ 已收藏过');return;}
  favs.unshift({text:d.text,label:d.label,time:new Date().toISOString(),type:promptType});
  localStorage.setItem('qg_prompt_favs',JSON.stringify(favs));
  toast('⭐ 已收藏到'+(promptType==='cover'?'封面':'社群'));
}

function getFavs(){try{return JSON.parse(localStorage.getItem('qg_prompt_favs')||'[]');}catch(e){return[];}}

function renderPromptLib(){
  var el=document.getElementById('promptLibContent');
  var meta=document.getElementById('promptLibMeta');
  var btn=document.getElementById('btnExtract');
  var favs=getFavs();
  var typeFavs=favs.filter(function(f){return (f.type||'cover')===recipeType;});
  var q=(document.getElementById('recipeSearch').value||'').toLowerCase();
  if(q)typeFavs=typeFavs.filter(function(f){
    return (f.label||'').toLowerCase().indexOf(q)>=0||f.text.toLowerCase().indexOf(q)>=0;
  });
  var typeIdxs=typeFavs.map(function(f){
    return favs.findIndex(function(x){return x.text===f.text&&x.time===f.time;});
  });
  
  var sel=selectedFavs.filter(function(s){return typeIdxs.includes(s);});
  meta.textContent=typeFavs.length+'/'+favs.length+'条 · 已选'+sel.length;
  btn.disabled=sel.length<3;
  btn.textContent=sel.length>=3?'🧠 提炼配方（'+sel.length+'条）':'🧠 提炼配方（需选≥3条）';
  
  if(!typeFavs.length){
    el.innerHTML='<div style="padding:16px;color:var(--text-dim);font-size:12px;text-align:center">'+
      (q?'无匹配':'暂无 '+recipeTypeMap[recipeType]+' 收藏')+'</div>';return;
  }
  
  var html='<div style="display:flex;gap:8px;padding:0 8px 8px;font-size:10px;color:var(--text-dim)">'+
    '<span onclick="selectAll()" style="cursor:pointer;color:var(--brand)">全选</span>'+
    '<span onclick="clearSel()" style="cursor:pointer;color:var(--text-dim)">清空</span>'+
    '</div>';
  
  typeFavs.forEach(function(f,i){
    var idx=typeIdxs[i];
    var checked=selectedFavs.includes(idx);
    var bodyId='favBody_'+idx;
    var nameId='favName_'+idx;
    html+='<div style="padding:6px 8px;border-bottom:1px solid var(--border);font-size:11px'+(checked?'background:var(--brand-light)':'')+'">'+
      '<div style="display:flex;align-items:center;gap:6px;cursor:pointer" onclick="toggleSel('+idx+')">'+
      '<span style="font-size:14px;flex-shrink:0;width:18px;text-align:center;color:'+(checked?'var(--brand)':'var(--text-dim)')+'">'+(checked?'☑':'☐')+'</span>'+
      '<span id="'+nameId+'" style="color:var(--text);font-weight:600;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(f.label||'未命名')+'</span>'+
      '<span onclick="event.stopPropagation();renameFav('+idx+')" style="color:var(--brand);font-size:10px;cursor:pointer" title="改名">✏️</span>'+
      '<span onclick="event.stopPropagation();toggleFavBody(\''+bodyId+'\',this)" style="color:var(--text-dim);font-size:10px;cursor:pointer" title="展开">▼</span>'+
      '<span onclick="event.stopPropagation();removeFavByIdx('+idx+')" style="color:var(--red);cursor:pointer;font-size:10px">🗑</span>'+
      '</div>'+
      '<div id="'+bodyId+'" style="display:none;margin-top:6px;padding:6px 8px;background:var(--bg);border-radius:4px;font-size:11px;line-height:1.6;color:var(--text-dim);white-space:pre-wrap;max-height:120px;overflow-y:auto">'+(f.text||'')+'</div>'+
    '</div>';
  });
  el.innerHTML=html;
  renderRecipeHistory();
}

function toggleFavBody(id,el){
  var div=document.getElementById(id);
  if(div.style.display==='none'||!div.style.display){
    div.style.display='block';el.textContent='▲';
  }else{
    div.style.display='none';el.textContent='▼';
  }
}

function renameFav(idx){
  var nameId='favName_'+idx;
  var span=document.getElementById(nameId);
  if(!span)return;
  var old=span.textContent;
  var input=document.createElement('input');
  input.value=old;input.style.cssText='flex:1;min-width:0;padding:2px 4px;border:1px solid var(--brand);border-radius:4px;font-size:11px;font-weight:600;color:var(--text);background:#fff';
  input.onblur=function(){finishRename(idx,input.value);};
  input.onkeydown=function(e){if(e.key==='Enter'){input.blur();e.preventDefault();}};
  span.parentNode.replaceChild(input,span);
  input.focus();input.select();
}

function finishRename(idx,val){
  var favs=getFavs();
  if(favs[idx]){favs[idx].label=val||favs[idx].label||'未命名';}
  localStorage.setItem('qg_prompt_favs',JSON.stringify(favs));
  renderPromptLib();
}

var selectedFavs=[];
function toggleSel(idx){
  var p=selectedFavs.indexOf(idx);
  if(p>=0)selectedFavs.splice(p,1);else selectedFavs.push(idx);
  renderPromptLib();
}
function selectAll(){
  var favs=getFavs();
  var typeFavs=favs.filter(function(f){return (f.type||'cover')===recipeType;});
  selectedFavs=typeFavs.map(function(f){return favs.findIndex(function(x){return x.text===f.text&&x.time===f.time;});});
  renderPromptLib();
}
function clearSel(){selectedFavs=[];renderPromptLib();}
function removeFavByIdx(idx){
  var favs=getFavs();favs.splice(idx,1);
  localStorage.setItem('qg_prompt_favs',JSON.stringify(favs));
  selectedFavs=selectedFavs.filter(function(s){return s!==idx;});
  // Reindex remaining
  selectedFavs=selectedFavs.map(function(s){return s>idx?s-1:s;});
  renderPromptLib();
}
function reuseFav(idx){
  var favs=getFavs().filter(function(f){return (f.type||'cover')===recipeType;});
  var f=favs[idx];
  if(!f)return;
  var el=document.getElementById('recipeOutput');
  el.innerHTML='<div style="font-size:11px;color:var(--text-dim);margin-bottom:4px">📌 选中</div>'+
    renderPromptCard(f.text,f.label,'📌');
  window.scrollTo({top:el.offsetTop-20,behavior:'smooth'});
}

function removeFav(idx){
  var favs=getFavs();
  var typeFavs=favs.filter(function(f){return (f.type||'cover')===recipeType;});
  var target=typeFavs[idx];
  if(!target)return;
  favs=favs.filter(function(f){return f.text!==target.text||f.time!==target.time;});
  localStorage.setItem('qg_prompt_favs',JSON.stringify(favs));
  renderPromptLib();
}

function renderRecipeHistory(){
  var el=document.getElementById('recipeOutput');
  var recipes=getRecipes();
  var key=recipeType;
  if(!recipes[key]||!recipes[key].length){
    el.innerHTML='<div style="padding:40px;text-align:center;color:var(--text-dim)">暂无'+recipeTypeMap[recipeType]+'配方</div>';
    return;
  }
  var list=recipes[key];
  var html='';
  list.forEach(function(r,i){
    var collapsed=r.text.length>200;
    var bodyId='recipeBody_'+i;
    var display=collapsed?'max-height:60px;overflow:hidden':'';
    html+='<div style="background:#fff;border-radius:var(--radius-sm);padding:12px;margin-bottom:8px;border:1px solid var(--border)">'+
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">'+
      '<div style="font-size:11px;font-weight:600;color:var(--brand)">🧪 '+recipeTypeMap[recipeType]+' · '+(r.time||'').substring(0,10)+' · '+r.count+'条</div>'+
      '<div style="display:flex;gap:4px">'+
      '<button class="btn btn-ghost" onclick="navigator.clipboard.writeText(document.getElementById(\''+bodyId+'\').textContent);toast(\'📋 已复制\')" style="font-size:10px;padding:2px 6px">📋</button>'+
      '<button class="btn btn-ghost" onclick="delRecipe(\''+key+'\','+i+')" style="font-size:10px;color:var(--red);padding:2px 6px">🗑</button>'+
      '</div></div>'+
      '<div id="'+bodyId+'" class="recipe-body" style="font-size:11px;line-height:1.7;color:var(--text);white-space:pre-wrap;'+display+';background:var(--bg);padding:8px;border-radius:4px">'+r.text+'</div>'+
      (collapsed?'<div style="text-align:center;margin-top:4px"><span onclick="toggleRecipeBody(\''+bodyId+'\',this)" style="font-size:10px;color:var(--brand);cursor:pointer">展开全部 ▼</span></div>':'')+
      '</div>';
  });
  el.innerHTML=html;
}

function toggleRecipeBody(id,el){
  var div=document.getElementById(id);
  if(div.style.maxHeight==='60px'||!div.style.maxHeight){
    div.style.maxHeight='none';div.style.overflow='visible';el.textContent='收起 ▲';
  }else{
    div.style.maxHeight='60px';div.style.overflow='hidden';el.textContent='展开全部 ▼';
  }
}

function delRecipe(key,idx){
  var recipes=getRecipes();
  recipes[key].splice(idx,1);
  saveRecipes(recipes);
  renderRecipeHistory();
}

function extractRecipe(){
  if(selectedFavs.length<3){toast('⚠️ 请先选择≥3条收藏');return;}
  var apiKey=getApiKey();
  if(!apiKey){toast('⚠️ 请先设置 API Key');return;}
  var favs=getFavs();
  var selFavs=selectedFavs.map(function(i){return favs[i];}).filter(Boolean);
  if(selFavs.length<3){toast('⚠️ 选择失效，请重新勾选');return;}
  var typeName=recipeTypeMap[recipeType];
  var samples=selFavs.map(function(f,i){return '【'+f.label+'】\n'+f.text;}).join('\n\n---\n\n');
  
  var promptText='你是切果NOW配图Prompt配方分析师。以下是「'+typeName+'」场景的'+selFavs.length+'条用户精选Prompt：\n\n'+
    samples+'\n\n'+
    '请提炼出：\n'+
    '1. 核心关键词（构图/布景/道具/光影/色调）\n'+
    '2. 优化合成的标准Prompt模板\n\n'+
    '输出格式：先总结关键词，再输出模板。全中文。';
  
  var btn=document.getElementById('btnExtract');
  btn.disabled=true;btn.textContent='⏳ 分析中...';
  toast('🧠 正在分析 '+selFavs.length+' 条配方...');
  
  fetch('https://api.deepseek.com/chat/completions',{
    method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+apiKey},
    body:JSON.stringify({model:'deepseek-chat',messages:[{role:'user',content:promptText}],max_tokens:1200})
  }).then(function(r){return r.json()}).then(function(d){
    var txt=d.choices?d.choices[0].message.content:'分析失败';
    var recipes=getRecipes();
    if(!recipes[recipeType])recipes[recipeType]=[];
    recipes[recipeType].unshift({text:txt,time:new Date().toISOString(),count:selFavs.length});
    saveRecipes(recipes);
    renderRecipeHistory();
    btn.disabled=false;btn.textContent='🧠 提炼配方（'+selFavs.length+'条）';
    toast('🧪 配方已保存');
  }).catch(function(e){
    btn.disabled=false;btn.textContent='🧠 提炼配方（'+selFavs.length+'条）';
    toast('⚠️ '+e.message);
  });
}

